#include <stdint.h>

const uint8_t mask = 0x01;

void setup() {
  uint8_t cppValue = 0x0F;
  cppValue ^= mask;  // taşınabilir C++ sonucu: 0x0E

  uint8_t asmValue = 0x0F;
  // AVR-GCC'ye özgü inline assembly; her Arduino kartında taşınabilir değildir.
  asm volatile (
    "eor %0, %1"
    : "+r" (asmValue)  // çıktı: yazmaçta okunur ve yazılır
    : "r" (mask)       // girdi: mask bir yazmaçtadır
    : "cc"              // EOR koşul bayraklarını değiştirir
  );                  // asmValue de 0x0E olur
  Serial.begin(9600);
  Serial.print(cppValue);
  Serial.print(' ');
  Serial.println(asmValue);  // yalnız örnek çıktısı; Serial süresini ölçmeyin
}

void loop() {}
